class Card {
  constructor() {
    console.log(this.badge());
  }
  get label() {
    return "card";
  }
  badge() {
    return this.label + ":" + this.tier;
  }
}

class GoldCard extends Card {
  tier = "gold";
  get label() {
    return "vip";
  }
  run = () => "gold-run";
}

class BlackCard extends GoldCard {
  run() {
    return "black-run";
  }
}

const card = new BlackCard();
console.log(card.badge());
console.log(card.run());
